  }

  OPTIONAL {
    ?cashFlow ex:cashFlowType "Deposit" .
    ?cashFlow ex:amount ?depositAmount .
  }
}
GROUP BY ?investorName
HAVING (SUM(xsd:decimal(?withdrawalAmount)) > 0 && SUM(xsd:decimal(?depositAmount)) > 0)
BIND(SUM(xsd:decimal(?withdrawalAmount)) / SUM(xsd:decimal(?depositAmount)) AS ?ratio)

